//============================================================================
//  TMS36XX family organ / melody generator: MM6221AA (Phoenix), TMS3615 (Pleiads), TMS3617
//
//  RTL port of MAME sound/tms36xx.cpp (license:BSD-3-Clause, copyright-holders: Juergen Buchmueller),
//  integer arithmetic as MAME. Derived from the Sega G80 core's rtl/sound/tms36xx.sv (TMS3615 / TMS3617 only),
//  extended with the MM6221AA tune sequencer and fixed tunes 1-3 (tables generated by tools/tms36xx_tunes.py).
//
//  Twelve voice slots, two banks of six; a strike flips the bank and restarts the six harmonics of the next step
//  (16', 8', 5 1/3', 4', 2 2/3', 2') at full volume, the other bank decays on. Per output sample: decay all
//  twelve, advance the tune, tone all twelve; output = sum of the high voices / (2 x enabled harmonics).
//  Tune 0 (MM6221AA idle) or no enabled harmonic outputs 0. The DC blocker at the end stands in for the
//  board's coupling capacitor.
//============================================================================

`default_nettype none

module tms36xx #(
    parameter int unsigned CLK_HZ    = 44_000_000,  // system clock
    parameter int unsigned BASEFREQ  =        372,  // sample rate = BASEFREQ * 64
    parameter int unsigned SPEED     =          0,  // VMAX / tune speed (0 = not set)
    // Decay times in ms, per harmonic; 0 disables a voice.
    parameter int unsigned DECAY0_MS =        500,
    parameter int unsigned DECAY1_MS =          0,
    parameter int unsigned DECAY2_MS =          0,
    parameter int unsigned DECAY3_MS =       1050,
    parameter int unsigned DECAY4_MS =          0,
    parameter int unsigned DECAY5_MS =          0,
    // Second configuration, selected at run time by cfg_b (one pooled instance serves two boards). Defaults:
    // Pleiads TMS3615 at 247, decays 0.33 s on harmonics 0, 1, 3, 5, no tune speed.
    parameter int unsigned BASEFREQ_B  =      247,
    parameter int unsigned SPEED_B     =        0,
    parameter int unsigned DECAY0_MS_B =      330,
    parameter int unsigned DECAY1_MS_B =      330,
    parameter int unsigned DECAY2_MS_B =        0,
    parameter int unsigned DECAY3_MS_B =      330,
    parameter int unsigned DECAY4_MS_B =        0,
    parameter int unsigned DECAY5_MS_B =      330
)(
    input  wire                clk,
    input  wire                reset,
    input  wire                cfg_b,         // 0 = the first parameter set, 1 = the _B set (static between resets)

    input  wire                tune_we,       // MM6221AA: tune select
    input  wire         [1:0]  tune,

    input  wire                note_we,       // TMS3615 / TMS3617: strike a note
    input  wire         [1:0]  note_octave,
    input  wire         [3:0]  note,          // 0-12 valid, 13-15 ignored

    input  wire                enable_we,     // TMS3617 voice enable mask
    input  wire         [5:0]  voice_enable,

    output wire signed [15:0]  audio,
    output wire                ce_snd         // one pulse per output sample
);

    localparam int unsigned SAMPLERATE = BASEFREQ * 64;
    localparam int unsigned VMAX       = 32767;

    localparam signed [25:0] SR_VOL  = 26'(SAMPLERATE);
    localparam signed [18:0] SR_TONE = 19'(SAMPLERATE);
    localparam signed [31:0] SR_TUNE = 32'(SAMPLERATE);

    // decay rate = VMAX / decay seconds
    localparam int unsigned DEC0 = (DECAY0_MS != 0) ? (VMAX * 1000) / DECAY0_MS : 0;
    localparam int unsigned DEC1 = (DECAY1_MS != 0) ? (VMAX * 1000) / DECAY1_MS : 0;
    localparam int unsigned DEC2 = (DECAY2_MS != 0) ? (VMAX * 1000) / DECAY2_MS : 0;
    localparam int unsigned DEC3 = (DECAY3_MS != 0) ? (VMAX * 1000) / DECAY3_MS : 0;
    localparam int unsigned DEC4 = (DECAY4_MS != 0) ? (VMAX * 1000) / DECAY4_MS : 0;
    localparam int unsigned DEC5 = (DECAY5_MS != 0) ? (VMAX * 1000) / DECAY5_MS : 0;

    // ...and the initial enable mask, one bit per harmonic with a decay set.
    localparam [5:0] INIT_EN = { DECAY5_MS != 0, DECAY4_MS != 0, DECAY3_MS != 0,
                                DECAY2_MS != 0, DECAY1_MS != 0, DECAY0_MS != 0 };

    //------------------------------------------------------------------------
    // Sample tick
    //------------------------------------------------------------------------
    localparam [32:0] ACC_INC = 33'((longint'(SAMPLERATE) <<< 32) / longint'(CLK_HZ));

    // the _B set, same derivations
    localparam int unsigned SAMPLERATE_B = BASEFREQ_B * 64;
    localparam int unsigned DEC0_B = (DECAY0_MS_B != 0) ? (VMAX * 1000) / DECAY0_MS_B : 0;
    localparam int unsigned DEC1_B = (DECAY1_MS_B != 0) ? (VMAX * 1000) / DECAY1_MS_B : 0;
    localparam int unsigned DEC2_B = (DECAY2_MS_B != 0) ? (VMAX * 1000) / DECAY2_MS_B : 0;
    localparam int unsigned DEC3_B = (DECAY3_MS_B != 0) ? (VMAX * 1000) / DECAY3_MS_B : 0;
    localparam int unsigned DEC4_B = (DECAY4_MS_B != 0) ? (VMAX * 1000) / DECAY4_MS_B : 0;
    localparam int unsigned DEC5_B = (DECAY5_MS_B != 0) ? (VMAX * 1000) / DECAY5_MS_B : 0;
    localparam [5:0] INIT_EN_B = { DECAY5_MS_B != 0, DECAY4_MS_B != 0, DECAY3_MS_B != 0,
                                  DECAY2_MS_B != 0, DECAY1_MS_B != 0, DECAY0_MS_B != 0 };
    localparam [32:0] ACC_INC_B = 33'((longint'(SAMPLERATE_B) <<< 32) / longint'(CLK_HZ));

    // the active set
    wire        [32:0] acc_inc    = cfg_b ? ACC_INC_B : ACC_INC;
    wire signed [25:0] sr_vol     = cfg_b ? 26'(SAMPLERATE_B) : SR_VOL;
    wire signed [18:0] sr_tone    = cfg_b ? 19'(SAMPLERATE_B) : SR_TONE;
    wire signed [31:0] sr_tune    = cfg_b ? 32'(SAMPLERATE_B) : SR_TUNE;
    wire        [31:0] speed_v    = cfg_b ? 32'(SPEED_B) : 32'(SPEED);
    wire        [15:0] basefreq_v = cfg_b ? 16'(BASEFREQ_B) : 16'(BASEFREQ);
    wire         [5:0] init_en    = cfg_b ? INIT_EN_B : INIT_EN;
    wire        [25:0] dec_h0 = cfg_b ? 26'(DEC0_B) : 26'(DEC0), dec_h1 = cfg_b ? 26'(DEC1_B) : 26'(DEC1),
                       dec_h2 = cfg_b ? 26'(DEC2_B) : 26'(DEC2), dec_h3 = cfg_b ? 26'(DEC3_B) : 26'(DEC3),
                       dec_h4 = cfg_b ? 26'(DEC4_B) : 26'(DEC4), dec_h5 = cfg_b ? 26'(DEC5_B) : 26'(DEC5);

    reg [32:0] ce_acc = '0;
    always @(posedge clk) ce_acc <= {1'b0, ce_acc[31:0]} + acc_inc;
    wire smp_tick = ce_acc[32];

    //------------------------------------------------------------------------
    // Tune ROM: tunes 1-3 (96 steps) then tune 4 (13 notes), 6 harmonics per step; registered (block RAM)
    //------------------------------------------------------------------------
    reg  [10:0] rom_a;
    reg  [14:0] rom_q;
    // array + initial block + clocked read: the form Quartus maps to M10K (as jt49_exp's lut); a case ROM stayed in logic
    reg  [14:0] tune_rom [0:2047];
    always @(posedge clk) rom_q <= tune_rom[rom_a];
    initial begin
// TUNES-BEGIN (generated by tools/tms36xx_tunes.py from MAME tms36xx.cpp; do not edit)
