        tune_rom[1924] = 15'd0;
        tune_rom[1925] = 15'd0;
        tune_rom[1926] = 15'd0;
        tune_rom[1927] = 15'd0;
        tune_rom[1928] = 15'd0;
        tune_rom[1929] = 15'd0;
        tune_rom[1930] = 15'd0;
        tune_rom[1931] = 15'd0;
        tune_rom[1932] = 15'd0;
        tune_rom[1933] = 15'd0;
        tune_rom[1934] = 15'd0;
        tune_rom[1935] = 15'd0;
        tune_rom[1936] = 15'd0;
        tune_rom[1937] = 15'd0;
        tune_rom[1938] = 15'd0;
        tune_rom[1939] = 15'd0;
        tune_rom[1940] = 15'd0;
        tune_rom[1941] = 15'd0;
        tune_rom[1942] = 15'd0;
