        tune_rom[1952] = 15'd0;
        tune_rom[1953] = 15'd0;
        tune_rom[1954] = 15'd0;
        tune_rom[1955] = 15'd0;
        tune_rom[1956] = 15'd0;
        tune_rom[1957] = 15'd0;
        tune_rom[1958] = 15'd0;
