        tune_rom[1998] = 15'd0;
        tune_rom[1999] = 15'd0;
        tune_rom[2000] = 15'd0;
        tune_rom[2001] = 15'd0;
        tune_rom[2002] = 15'd0;
        tune_rom[2003] = 15'd0;
        tune_rom[2004] = 15'd0;
        tune_rom[2005] = 15'd0;
        tune_rom[2006] = 15'd0;
        tune_rom[2007] = 15'd0;
        tune_rom[2008] = 15'd0;
        tune_rom[2009] = 15'd0;
        tune_rom[2010] = 15'd0;
        tune_rom[2011] = 15'd0;
        tune_rom[2012] = 15'd0;
        tune_rom[2013] = 15'd0;
