        tune_rom[2021] = 15'd0;
        tune_rom[2022] = 15'd0;
        tune_rom[2023] = 15'd0;
        tune_rom[2024] = 15'd0;
        tune_rom[2025] = 15'd0;
        tune_rom[2026] = 15'd0;
        tune_rom[2027] = 15'd0;
        tune_rom[2028] = 15'd0;
        tune_rom[2029] = 15'd0;
        tune_rom[2030] = 15'd0;
        tune_rom[2031] = 15'd0;
        tune_rom[2032] = 15'd0;
        tune_rom[2033] = 15'd0;
        tune_rom[2034] = 15'd0;
        tune_rom[2035] = 15'd0;
        tune_rom[2036] = 15'd0;
        tune_rom[2037] = 15'd0;
        tune_rom[2038] = 15'd0;
        tune_rom[2039] = 15'd0;
        tune_rom[2040] = 15'd0;
        tune_rom[2041] = 15'd0;
        tune_rom[2042] = 15'd0;
        tune_rom[2043] = 15'd0;
        tune_rom[2044] = 15'd0;
        tune_rom[2045] = 15'd0;
        tune_rom[2046] = 15'd0;
        tune_rom[2047] = 15'd0;
// TUNES-END
    end

    // Per-harmonic decay rate (dec_v below). the two banks share it.

    // 32768/n, so a divide by the voice count (2n) becomes one multiply.
    function automatic [15:0] recip_of (input [2:0] n);
        begin
            case (n)
                3'd1:    recip_of = 16'd32768;
                3'd2:    recip_of = 16'd16384;
                3'd3:    recip_of = 16'd10922;
                3'd4:    recip_of = 16'd8192;
                3'd5:    recip_of = 16'd6553;
                3'd6:    recip_of = 16'd5461;
                default: recip_of = 16'd0;
            endcase
        end
    endfunction

    //------------------------------------------------------------------------
    // Voice and tune state
    //------------------------------------------------------------------------
    reg        [15:0] vol  [0:11];
    reg signed [25:0] volc [0:11];
    reg        [15:0] freq [0:11];
    reg signed [18:0] cnt  [0:11];
    reg        [11:0] outbit;

    reg        [11:0] en12;
    reg         [2:0] nvoices;      // enabled harmonics (the output divisor is 2x)
    reg               init_ld;
    reg               bank;         // active bank: slot offset 0 or 6

    reg         [2:0] tune_num;     // 0 none, 1-3 MM6221AA tunes, 4 single notes
    reg         [6:0] tune_ofs, tune_max;
    reg         [1:0] octave;
    reg signed [31:0] tc;           // tune counter
    reg signed [17:0] nc;           // note counter
    reg         [3:0] tn;           // n = whole sample periods the tune counter went through

    // Pending host writes, applied between samples
    reg               note_pend, tune_pend;
    reg         [3:0] note_r;
    reg         [1:0] oct_r, tune_r;
    reg               smp_pend;

    wire        [2:0] popcnt = 3'(voice_enable[0]) + 3'(voice_enable[1])
                             + 3'(voice_enable[2]) + 3'(voice_enable[3])
                             + 3'(voice_enable[4]) + 3'(voice_enable[5]);

    //------------------------------------------------------------------------
    // Sequencer
    //------------------------------------------------------------------------
    localparam [3:0] S_IDLE = 4'd0, S_DEC0 = 4'd1, S_DECL = 4'd2, S_TUNE = 4'd3, S_TCNT = 4'd4, S_NOTE = 4'd5,
                     S_ROMA = 4'd6, S_ROMW = 4'd7, S_RST = 4'd8, S_TON0 = 4'd9, S_TONL = 4'd10, S_FIN = 4'd11;

    reg  [3:0] state;
    reg  [3:0] v;
    reg  [2:0] j;
    reg [20:0] sum;

    // RESTART: tunes[n][ofs*6 + j] * (basefreq << octave) / FSCALE (shift before the truncating divide)
    wire [45:0] f_prod  = (46'(rom_q) * 46'(basefreq_v)) << octave;
    wire [15:0] f_new   = 16'(f_prod >> 10);
    wire [10:0] step_a  = (tune_num == 3'd4) ? 11'd1728 + 11'(tune_ofs) * 11'd6
                                             : 11'(tune_num - 3'd1) * 11'd576 + 11'(tune_ofs) * 11'd6;

    wire [3:0]  slot    = bank ? (4'd6 + 4'(j)) : 4'(j);
    wire signed [17:0] nc_n = nc - $signed({14'd0, tn});   // note counter -= n (signed: an unsigned cast makes the test unsigned)
    wire [2:0]  dec_hn  = (v >= 4'd6) ? (v[2:0] - 3'd6) : v[2:0];
    reg  [25:0] dec_v;
    always @(*) begin
        case (dec_hn)
            3'd0:    dec_v = dec_h0;
            3'd1:    dec_v = dec_h1;
            3'd2:    dec_v = dec_h2;
            3'd3:    dec_v = dec_h3;
            3'd4:    dec_v = dec_h4;
            default: dec_v = dec_h5;
        endcase
    end
    wire [3:0]  nxt_v   = v + 4'd1;

    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < 12; i = i + 1) begin
                vol[i]  <= 16'd0;
                volc[i] <= 26'sd0;
                freq[i] <= 16'd0;
                cnt[i]  <= 19'sd0;
            end
            outbit    <= 12'd0;
            en12      <= 12'd0;                // initial enable mask: loaded on the first clock after reset (init_ld)
            nvoices   <= 3'd0;
            init_ld   <= 1'b1;
            bank      <= 1'b0;
            tune_num  <= 3'd0;
            tune_ofs  <= 7'd0;
            tune_max  <= 7'd0;
            octave    <= 2'd0;
            tc        <= 32'sd0;
            nc        <= 18'sd0;
            tn        <= 4'd0;
            smp_pend  <= 1'b0;
            note_pend <= 1'b0;
            tune_pend <= 1'b0;
            note_r    <= 4'd0;
            oct_r     <= 2'd0;
            tune_r    <= 2'd0;
            rom_a     <= 11'd0;
            state     <= S_IDLE;
            v         <= 4'd0;
            j         <= 3'd0;
            sum       <= 21'd0;
        end else begin
            if (smp_tick) smp_pend <= 1'b1;

            if (init_ld) begin                      // load the initial enable mask for the active configuration
                init_ld <= 1'b0;
                en12    <= {init_en, init_en};
                nvoices <= 3'(init_en[0]) + 3'(init_en[1]) + 3'(init_en[2])
                         + 3'(init_en[3]) + 3'(init_en[4]) + 3'(init_en[5]);
            end

            // notes above 12 are ignored
            if (note_we && (note <= 4'd12)) begin
                note_pend <= 1'b1;
                note_r    <= note;
                oct_r     <= note_octave;
            end
            // tune select (the same-tune check is made when it is applied)
            if (tune_we) begin
                tune_pend <= 1'b1;
                tune_r    <= tune;
            end
            // voice enable mask
            if (enable_we) begin
                en12    <= {voice_enable, voice_enable};
                nvoices <= popcnt;
            end

            case (state)
            S_IDLE:
                if (note_pend) begin                    // reset counters, then tune 4 = the one note
                    note_pend <= 1'b0;
                    tc <= 32'sd0;
                    nc <= 18'sd0;
                    for (i = 0; i < 12; i = i + 1) begin
                        volc[i] <= 26'sd0;
                        cnt[i]  <= 19'sd0;
                    end
                    octave   <= oct_r;
                    tune_num <= 3'd4;
                    tune_ofs <= 7'(note_r);
                    tune_max <= 7'(note_r) + 7'd1;
                end else if (tune_pend) begin
                    tune_pend <= 1'b0;
                    if ({1'b0, tune_r} != tune_num) begin
                        tune_num <= {1'b0, tune_r};
                        tune_ofs <= 7'd0;
                        tune_max <= 7'd96;
                    end
                end else if (smp_pend) begin
                    smp_pend <= 1'b0;
                    v        <= 4'd0;
                    sum      <= 21'd0;
                    state    <= (tune_num == 3'd0 || nvoices == 3'd0) ? S_FIN : S_DEC0;
                end

            // ---- DECAY(v) -----------------------------------------------
            S_DEC0:
                if (vol[v] != 16'd0) begin
                    volc[v] <= volc[v] - $signed({1'b0, dec_v[24:0]});
                    state   <= S_DECL;
                end else begin
                    v     <= nxt_v;
                    state <= (nxt_v == 4'd12) ? S_TUNE : S_DEC0;
                end

            S_DECL:
                if (volc[v] <= 26'sd0) begin
                    volc[v] <= volc[v] + sr_vol;
                    if (vol[v] == 16'd0) begin
                        freq[v] <= 16'd0;
                        v       <= nxt_v;
                        state   <= (nxt_v == 4'd12) ? S_TUNE : S_DEC0;
                    end else begin
                        vol[v] <= vol[v] - 16'd1;
                    end
                end else begin
                    v     <= nxt_v;
                    state <= (nxt_v == 4'd12) ? S_TUNE : S_DEC0;
                end

            // ---- musical note timing ----------------------------------------
            S_TUNE: begin
                tc    <= tc - $signed(speed_v);
                tn    <= 4'd0;
                v     <= 4'd0;                           // the tone loop starts at voice 0
                state <= S_TCNT;
            end

            S_TCNT:                                      // n = -tc / samplerate + 1; tc += n * samplerate
                if (tc <= 32'sd0) begin
                    tc <= tc + sr_tune;
                    tn <= tn + 4'd1;
                end else
                    state <= (tn != 4'd0) ? S_NOTE : S_TON0;

            S_NOTE:
                if (nc_n <= 18'sd0) begin
                    nc <= nc_n + 18'sd32767;
                    if (tune_ofs < tune_max) begin
                        bank  <= ~bank;                  // shift to the other bank, restart it
                        j     <= 3'd0;
                        rom_a <= step_a;
                        state <= S_ROMA;
                    end else
                        state <= S_TON0;
                end else begin
                    nc    <= nc_n;
                    state <= S_TON0;
                end

            S_ROMA: state <= S_ROMW;                     // ROM address registered
            S_ROMW: state <= S_RST;                      // ROM data registered

            S_RST: begin
                if (rom_q != 15'd0) begin               // RESTART(j) only for a non-zero table entry
                    freq[slot] <= f_new;
                    vol[slot]  <= 16'(VMAX);
                end
                j     <= j + 3'd1;
                rom_a <= rom_a + 11'd1;
                if (j == 3'd5) begin
                    tune_ofs <= tune_ofs + 7'd1;
                    state    <= S_TON0;
                end else
                    state <= S_ROMW;
            end

            // ---- TONE(v) -------------------------------------------------
            S_TON0:
                if (v == 4'd12)
                    state <= S_FIN;
                else if (en12[v] && (freq[v] != 16'd0)) begin
                    cnt[v] <= cnt[v] - $signed({3'b0, freq[v]});
                    state  <= S_TONL;
                end else
                    v <= nxt_v;

            S_TONL:
                if (cnt[v] <= 19'sd0) begin
                    cnt[v]     <= cnt[v] + sr_tone;
                    outbit[v]  <= ~outbit[v];
                end else begin
                    if (outbit[v] && en12[v]) sum <= sum + 21'(vol[v]);
                    v     <= nxt_v;
                    state <= S_TON0;
                end

            S_FIN:
                state <= S_IDLE;

            default: state <= S_IDLE;
            endcase
        end
    end

    //------------------------------------------------------------------------
    // Output: sum / voices.
    //------------------------------------------------------------------------
    wire [36:0] scaled = 37'(sum) * 37'(recip_of(nvoices));
    wire [15:0] level  = (scaled[36:32] != 5'd0) ? 16'hFFFF : scaled[31:16];

    // The stream is unipolar; this stands in for the board's coupling cap.
    reg signed [31:0] dc_acc;
    reg signed [15:0] audio_r;
    reg               ce_r;

    wire signed [31:0] lvl_q8 = $signed({8'd0, level, 8'd0});
    wire signed [31:0] hp     = $signed({16'd0, level}) - $signed({{8{dc_acc[31]}}, dc_acc[31:8]});

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            dc_acc  <= 32'sd0;
            audio_r <= 16'sd0;
            ce_r    <= 1'b0;
        end else begin
            ce_r <= (state == S_FIN);
            if (state == S_FIN) begin
                dc_acc  <= dc_acc + ((lvl_q8 - dc_acc) >>> 11);
                audio_r <= (hp >  32'sd32767) ?  16'sd32767 :
                           (hp < -32'sd32768) ? -16'sd32768 : hp[15:0];
            end
        end
    end

    assign audio  = audio_r;
    assign ce_snd = ce_r;

endmodule

`default_nettype wire
